# --------------------------------------------------
# RUNAWAY "NO" BUTTON
# --------------------------------------------------
def runaway_button():
    components.html(
        """
<!DOCTYPE html>
<html lang="ca">
<head>
<meta charset="utf-8">

<style>
* {
box-sizing: border-box;
}

body {
margin: 0;
overflow: hidden;
background: transparent;
font-family: Arial, sans-serif;
}

#arena {
height: 225px;
width: 100%;
position: relative;
overflow: hidden;
}

#noBtn {
position: absolute;
left: 50%;
top: 15px;
transform: translateX(-50%);

background: #F1E8E1;
color: #8E7169;
border: 1px solid #D8C8BD;
border-radius: 14px;

padding: 15px 35px;
font-size: 16px;
font-weight: bold;

cursor: pointer;
white-space: nowrap;

transition: left .45s ease-in-out, top .45s ease-in-out;
touch-action: none;
}

#message {
position:absolute;bottom:4px;left:0;width:100%;
padding:17px 20px;min-height:76px;display:flex;
align-items:center;justify-content:center;text-align:center;
color:#8b7669;font-size:13px;line-height:1.35;
border:1px dashed #cbbda5;border-radius:3px;
transition:background .2s,color .2s;
}
#message.active {
background:#bc3038;color:#fffefa;border:1px solid #bc3038;
font-family:Georgia,serif;font-size:clamp(20px,4.5vw,27px);
font-weight:bold;box-shadow:4px 4px 0 #ded0b7;
animation:pop .3s ease;
}
#message.active:before {content:"✦";font-size:24px;margin-right:14px;color:#e4c38d;}
@keyframes pop {from {transform:translateY(6px);opacity:.4;}to {transform:translateY(0);opacity:1;}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;}}
</style>
</head>

<body>
<div id="arena">
<button id="noBtn" type="button">
NO 🙈
</button>

<div id="message" role="status" aria-live="polite" aria-atomic="true">
També hi ha aquesta opció... en teoria.
</div>
</div>

<script>
const btn = document.getElementById("noBtn");
const arena = document.getElementById("arena");
const message = document.getElementById("message");

const phrases = [
"Aquesta opció no està disponible!",
"Segur que no et vols equivocar...",
"El xef italià no accepta aquesta resposta.",
"Ui! Aquest botó es fa el tímid…",
"Potser és un senyal del destí...",
"A Barcelona també sabem dir que sí!"
];

let lastMove = 0;
let pendingMove = null;
let attempts = 0;

function escapeButton(event) {
if (event) {
event.preventDefault();
}

const now = Date.now();

if (now - lastMove < 1100) {
return;
}

lastMove = now;

const maxX = Math.max(
0,
arena.clientWidth - btn.offsetWidth - 10
);

const maxY = Math.max(
0,
arena.clientHeight - btn.offsetHeight - 100
);

const x = 5 + Math.random() * maxX;
const y = Math.random() * maxY;

btn.style.transform = "none";
btn.style.left = x + "px";
btn.style.top = y + "px";

message.classList.remove("active");
void message.offsetWidth;
message.classList.add("active");
message.textContent = phrases[attempts % phrases.length];
attempts++;

}

// One gentle move per deliberate attempt; no proximity tracking.
function scheduleEscape() {
if (pendingMove !== null || Date.now() - lastMove < 1100) return;
pendingMove = setTimeout(() => {
pendingMove = null;
escapeButton();
}, 300);
}
btn.addEventListener("pointerenter", scheduleEscape);
btn.addEventListener("pointerleave", () => {
if (pendingMove !== null) clearTimeout(pendingMove);
pendingMove = null;
});
btn.addEventListener("click", event => {
event.preventDefault();
scheduleEscape();
});
</script>
</body>
</html>
""",
        height=230,
        scrolling=False,
    )



def barca_rain():
    """A brief, non-interactive shower of crests on the confirmation screen."""
    crest = 'data:image/svg+xml;base64,'
    pieces = []
    for i in range(24):
        left = (i * 41 + 7) % 98
        delay = (i % 8) * 0.45
        duration = 6 + (i % 4) * 0.6
        size = 28 + (i % 4) * 7
        pieces.append(f'<img alt="" src="{crest}" style="left:{left}%;width:{size}px;animation-delay:{delay}s;animation-duration:{duration}s;--drift:{(i % 5 - 2) * 25}px;--spin:{(i % 3 - 1) * 100}deg">')
    st.markdown('<style>.barca-rain{position:fixed;inset:0;overflow:hidden;pointer-events:none;z-index:999990}.barca-rain img{position:absolute;top:-90px;height:auto;opacity:0;animation:barca-fall linear both;filter:drop-shadow(0 3px 4px #0002)}@keyframes barca-fall{0%{opacity:0;transform:translate(0,-50px) rotate(-15deg)}8%{opacity:.85}88%{opacity:.85}100%{opacity:0;transform:translate(var(--drift),calc(100vh + 140px)) rotate(var(--spin))}}@media(prefers-reduced-motion:reduce){.barca-rain{display:none}}</style><div class="barca-rain" aria-hidden="true">'+''.join(pieces)+'</div>',unsafe_allow_html=True)

